css:
.loader { position: relative; display: inline-block; width: var(--loader-size); height: var(--loader-size); animation: twHeart calc(var(--loader-speed) * 1.2) ease-in-out infinite; }
.loader::before, .loader::after { content: ''; position: absolute; top: 18%; width: 50%; height: 76%; border-radius: calc(var(--loader-size) * .5) calc(var(--loader-size) * .5) 0 0; background: var(--loader-color); }
.loader::before { left: 50%; transform: rotate(-45deg); transform-origin: 0 100%; }
.loader::after { left: 0; transform: rotate(45deg); transform-origin: 100% 100%; }
@keyframes twHeart { 0%, 100% { transform: scale(.84); } 15% { transform: scale(1.06); } 30% { transform: scale(.92); } 45% { transform: scale(1); } }
